import type { Hand, HandGroup, HandLook, HandPhoto } from '../model/types';

/** Original artwork generated by handArt.ts. Names follow the reference product's picker so the sets map 1:1. */

const SKIN = {
  porcelain: '#f6dcc8',
  light: '#f2c4a0',
  tan: '#dba37a',
  medium: '#c08457',
  brown: '#93603e',
  deep: '#5f3b27',
  pale: '#efdccb',
  witch: '#6fa24a',
};

const groupOf = (id: string): HandGroup =>
  id.startsWith('witch') || id.startsWith('santa') ? 'Seasonal' : id.includes('chalk') ? 'Chalk' : id.includes('cartoon') ? 'Cartoon' : 'Realistic';

const hand = (id: string, name: string, look: HandLook, tier: Hand['tier'] = 'free'): Hand => ({ id, name, tier, look, group: groupOf(id) });

const real = (skin: string, build: HandLook['build'] = 'male'): HandLook => ({ skin, build, style: 'real', tool: 'marker' });
const cartoon = (skin: string, build: HandLook['build'] = 'male'): HandLook => ({ skin, build, style: 'cartoon', tool: 'pen' });

