export const HAND_GROUPS: HandGroup[] = ['Realistic', 'Chalk', 'Cartoon', 'Seasonal'];
/** Ids from older saves. */
const RENAMED: Record<string, string> = { 'santa-2': 'santa-glove' };
export const currentHandId = (id: string): string => RENAMED[id] ?? id;

export const DEFAULT_HAND_ID = 'male-9';

let byId = new Map(HANDS.map((h) => [h.id, h]));
/** The catalog, with photo versions once public/hands/hands.json has loaded. */
export const handById = (id: string): Hand | undefined => byId.get(currentHandId(id));

export const HAND_MANIFEST_URL = '/hands/hands.json';

interface ManifestEntry extends HandPhoto {
  id: string;
  name: string;
  premium: boolean;
  group: HandGroup;
}

let catalog: Promise<Hand[]> | null = null;

/**
 * Loads public/hands/hands.json once and attaches each photo to its hand (only the list: images load
 * when a hand is used). Hands without a photo keep their illustrated look; if the manifest can't be
 * read, every hand does.
 */
export function loadHandCatalog(): Promise<Hand[]> {
  catalog ??= fetch(HAND_MANIFEST_URL)
    .then((res) => (res.ok ? (res.json() as Promise<ManifestEntry[]>) : []))
    .catch(() => [] as ManifestEntry[])
    .then((entries) => {
      const photos = new Map(entries.map((e) => [e.id, e]));
      const hands = HANDS.map((h): Hand => {
        const e = photos.get(h.id);
        if (!e) return h;
        return { ...h, name: e.name, tier: e.premium ? 'pro' : 'free', group: e.group, photo: { file: e.file, png: e.png, thumb: e.thumb, tipX: e.tipX, tipY: e.tipY, arm: e.arm } };
      });
      byId = new Map(hands.map((h) => [h.id, h]));
      return hands;
    });
  return catalog;
}

/** A hand with its photo, if it has one. */
export async function resolveHand(id: string): Promise<Hand | undefined> {
  await loadHandCatalog();
  return handById(id);
}
